package com.internhub.service;
import com.internhub.dto.AdminDtos; import com.internhub.entity.*; import com.internhub.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant;
@Service public class AuditService { private final AuditLogRepository logs; private final UserRepository users; public AuditService(AuditLogRepository l,UserRepository u){logs=l;users=u;} @Transactional public void record(Long adminId,String action,String type,Long target,String details){var l=new AuditLog();l.setAdmin(users.getReferenceById(adminId));l.setAction(action);l.setTargetType(type);l.setTargetId(target);l.setDetails(details);l.setCreatedAt(Instant.now());logs.save(l);} @Transactional(readOnly=true) public Page<AdminDtos.AuditRow> list(Pageable p){return logs.findAllByOrderByCreatedAtDesc(p).map(AdminDtos.AuditRow::from);} }
